mapper.select:
SELECT id,batch_code,name AS batch_name,(SELECT MIN(examination_date) FROM public.health_examination_batch_days d WHERE d.batch_id=b.id) AS start_date,(SELECT MAX(examination_date) FROM public.health_examination_batch_days d WHERE d.batch_id=b.id) AS end_date,status,created_at,updated_at,row_version FROM public.health_examination_batches b WHERE ORDER BY
batch_code DESC, id ASC batch_code ASC, id ASC name DESC, id ASC name ASC, id ASC start_date DESC, id ASC start_date ASC, id ASC status DESC, id ASC status ASC, id ASC created_at DESC, id ASC created_at ASC, id ASC id DESC id ASC
LIMIT #{limit} OFFSET #{offset}
